{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { readFileSync } from 'fs'

// Parse command line arguments
const args = process.argv.slice(2)
if (args.length !== 1 || !['rounds', 'tally'].includes(args[0])) {
  process.stderr.write('error: usage: cli.js rounds|tally\n')
  process.exit(2)
}
const mode = args[0]

// Read stdin
let input = ''
try {
  input = readFileSync(0, 'utf8')
} catch (e) {
  // Handle EOF gracefully
}

// Parse the input
function error(lineNum, message) {
  process.stderr.write(`error: line ${lineNum}: ${message}\n`)
  process.exit(2)
}

function errorNoLine(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

// Split input on newlines and drop the empty tail a trailing newline leaves
const lines = input.split('\n')
if (lines.length > 0 && lines[lines.length - 1] === '') {
  lines.pop()
}

// Parse lines
let lineNum = 0
const parsedLines = []

for (const rawLine of lines) {
  lineNum++
  const line = rawLine.trim()

  // Ignore empty lines and comments
  if (line === '' || line.startsWith('#')) {
    continue
  }

  // Split on runs of whitespace
  const parts = line.split(/\s+/)
  parsedLines.push({ lineNum, parts })
}

// Parse candidates and ballots
let candidatesDeclared = false
let candidates = []
const candidatesSet = new Set()
const ballots = []

for (const { lineNum, parts } of parsedLines) {
  const directive = parts[0]

  if (directive === 'candidates') {
    if (candidatesDeclared) {
      error(lineNum, 'candidates must be declared once, before any ballot')
    }
    if (parts.length < 2) {
      error(lineNum, 'expected candidates <name>...')
    }

    candidates = parts.slice(1)
    for (const name of candidates) {
      // Validate candidate name
      if (!/^[A-Za-z0-9_-]+$/.test(name)) {
        error(lineNum, `invalid candidate name ${name}`)
      }

      // Check for duplicates
      if (candidatesSet.has(name)) {
        error(lineNum, `candidate ${name} is declared twice`)
      }
      candidatesSet.add(name)
    }

    candidatesDeclared = true
  } else if (directive === 'ballot') {
    if (!candidatesDeclared) {
      error(lineNum, 'candidates must be declared once, before any ballot')
    }

    if (parts.length < 2) {
      error(lineNum, 'expected ballot <count> <candidate>...')
    }

    // Parse count
    const countStr = parts[1]
    if (!/^\d+$/.test(countStr) || countStr === '0' || countStr[0] === '0' && countStr.length > 1) {
      error(lineNum, 'count must be a positive integer')
    }
    const count = parseInt(countStr, 10)
    if (count <= 0) {
      error(lineNum, 'count must be a positive integer')
    }

    // Parse ballot choices
    const choices = parts.slice(2)
    if (choices.length === 0) {
      error(lineNum, 'expected ballot <count> <candidate>...')
    }

    const seenInBallot = new Set()
    for (const choice of choices) {
      if (!candidatesSet.has(choice)) {
        error(lineNum, `unknown candidate ${choice}`)
      }
      if (seenInBallot.has(choice)) {
        error(lineNum, `candidate ${choice} is repeated`)
      }
      seenInBallot.add(choice)
    }

    ballots.push({ count, choices })
  } else {
    error(lineNum, `unknown directive ${directive}`)
  }
}

// Check that candidates were declared
if (!candidatesDeclared) {
  errorNoLine('no candidates')
}

// Initialize election state
const rounds = []
let continuing = new Set(candidates)

// Run the election
while (true) {
  // Count votes for this round
  const votes = {}
  for (const candidate of candidates) {
    votes[candidate] = 0
  }

  let exhausted = 0
  for (const { count, choices } of ballots) {
    let voted = false
    for (const choice of choices) {
      if (continuing.has(choice)) {
        votes[choice] += count
        voted = true
        break
      }
    }
    if (!voted) {
      exhausted += count
    }
  }

  // Calculate active total
  const activeTotal = Object.values(votes).reduce((a, b) => a + b, 0)

  // Store round results
  const roundVotes = {}
  for (const candidate of candidates) {
    roundVotes[candidate] = votes[candidate]
  }
  rounds.push({ votes: roundVotes, exhausted })

  // Check if someone won
  for (const candidate of candidates) {
    if (continuing.has(candidate) && votes[candidate] * 2 > activeTotal) {
      // Winner found
      if (mode === 'rounds') {
        printRounds(rounds, candidates)
      } else {
        process.stdout.write(`rounds ${rounds.length}\n`)
      }
      process.stdout.write(`winner ${candidate}\n`)
      process.exit(0)
    }
  }

  // Check if election has no winner
  if (activeTotal === 0) {
    if (mode === 'rounds') {
      printRounds(rounds, candidates)
    } else {
      process.stdout.write(`rounds ${rounds.length}\n`)
    }
    process.stdout.write('no winner\n')
    process.exit(0)
  }

  // Find candidate with fewest votes to eliminate
  const toEliminate = findToEliminate(continuing, rounds, candidates)

  if (mode === 'rounds') {
    printRound(rounds[rounds.length - 1], candidates)
    process.stdout.write(`eliminated ${toEliminate}\n`)
  }

  continuing.delete(toEliminate)
}

function findToEliminate(continuing, rounds, allCandidates) {
  const candidates = Array.from(continuing)

  if (candidates.length === 0) {
    return null
  }

  if (candidates.length === 1) {
    return candidates[0]
  }

  // Tie-breaking: compare across rounds from first to last
  let remaining = new Set(candidates)

  for (let roundIdx = 0; roundIdx < rounds.length; roundIdx++) {
    const roundVotes = rounds[roundIdx].votes

    // Find minimum votes among remaining candidates
    let minVotes = Infinity
    for (const candidate of remaining) {
      minVotes = Math.min(minVotes, roundVotes[candidate])
    }

    // Keep only those with minimum votes
    const newRemaining = new Set()
    for (const candidate of remaining) {
      if (roundVotes[candidate] === minVotes) {
        newRemaining.add(candidate)
      }
    }

    remaining = newRemaining

    if (remaining.size === 1) {
      return Array.from(remaining)[0]
    }
  }

  // If still tied, eliminate the one whose name sorts last by code point
  const sorted = Array.from(remaining).sort()
  return sorted[sorted.length - 1]
}

function printRound(roundData, candidates) {
  const { votes, exhausted } = roundData

  // Sort by descending votes, then ascending name
  const sorted = candidates
    .filter(c => votes[c] > 0 || true) // Include all candidates
    .sort((a, b) => {
      if (votes[b] !== votes[a]) {
        return votes[b] - votes[a]
      }
      return a.localeCompare(b)
    })

  const parts = []
  for (const candidate of sorted) {
    parts.push(`${candidate}=${votes[candidate]}`)
  }

  process.stdout.write(`round ${rounds.length}: ${parts.join(' ')} exhausted=${exhausted}\n`)
}

function printRounds(allRounds, allCandidates) {
  for (let i = 0; i < allRounds.length; i++) {
    const roundData = allRounds[i]
    const { votes, exhausted } = roundData

    // Sort by descending votes, then ascending name
    const sorted = allCandidates
      .sort((a, b) => {
        if (votes[b] !== votes[a]) {
          return votes[b] - votes[a]
        }
        return a.localeCompare(b)
      })

    const parts = []
    for (const candidate of sorted) {
      parts.push(`${candidate}=${votes[candidate]}`)
    }

    process.stdout.write(`round ${i + 1}: ${parts.join(' ')} exhausted=${exhausted}\n`)
  }
}
"}

